import os,re
root='/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild'
def src(m): return os.path.join(root,m.replace('.','/')+'.lean')
def ole(m): return os.path.join(root,'.lake/build/lib/lean',m.replace('.','/')+'.olean')
seen=set()
def walk(m):
    if m in seen: return
    seen.add(m)
    p=src(m)
    if not os.path.exists(p): return
    for line in open(p):
        x=re.match(r'import (AlgebraicJacobian[\w.]*)',line)
        if x: walk(x.group(1))
for m in ['AlgebraicJacobian.Picard.DivRepGlobalAffLift']: walk(m)
missing=[m for m in sorted(seen) if not os.path.exists(ole(m))]
print('closure',len(seen),'missing',len(missing))
for m in missing: print(' ',m)
EOF
